CREATE TRIGGER manual_asset_update BEFORE UPDATE ON manual_asset_details WHEN NEW.owner_id IS NOT OLD.owner_id OR NEW.account_id IS NOT OLD.account_id OR NOT EXISTS(SELECT 1 FROM accounts WHERE owner_id=NEW.owner_id AND id=NEW.account_id AND type IN ('property','vehicle') AND type=json_extract(NEW.details_json,'$.kind')) OR (json_extract(NEW.details_json,'$.kind')='property' AND ((SELECT count(*) FROM json_each(NEW.details_json))!=5 OR EXISTS(SELECT 1 FROM json_each(NEW.details_json) WHERE key NOT IN ('kind','yearBuilt','areaValue','areaUnit','address')))) OR (json_extract(NEW.details_json,'$.kind')='vehicle' AND ((SELECT count(*) FROM json_each(NEW.details_json))!=6 OR EXISTS(SELECT 1 FROM json_each(NEW.details_json) WHERE key NOT IN ('kind','make','model','year','mileageValue','mileageUnit')))) OR (json_type(NEW.details_json,'$.address')='object' AND ((SELECT count(*) FROM json_each(json_extract(NEW.details_json,'$.address')))!=7 OR EXISTS(SELECT 1 FROM json_each(json_extract(NEW.details_json,'$.address')) WHERE key NOT IN ('line1','line2','locality','region','country','postalCode','county')))) BEGIN SELECT RAISE(ABORT,'manual_asset_invalid'); END;
