CREATE TRIGGER manual_asset_family AFTER UPDATE OF type ON accounts WHEN NEW.type IS NOT OLD.type BEGIN DELETE FROM manual_asset_details WHERE owner_id=NEW.owner_id AND account_id=NEW.id; END;
--> statement-breakpoint
CREATE TRIGGER manual_asset_revision_insert AFTER INSERT ON manual_asset_details WHEN NOT EXISTS(SELECT 1 FROM workspace_guards WHERE owner_id=NEW.owner_id) BEGIN UPDATE profiles SET revision=revision+1 WHERE owner_id=NEW.owner_id; END;
--> statement-breakpoint
CREATE TRIGGER manual_asset_revision_update AFTER UPDATE ON manual_asset_details WHEN NEW.details_json IS NOT OLD.details_json AND NOT EXISTS(SELECT 1 FROM workspace_guards WHERE owner_id=NEW.owner_id) BEGIN UPDATE profiles SET revision=revision+1 WHERE owner_id=NEW.owner_id; END;
--> statement-breakpoint
CREATE TRIGGER manual_asset_revision_delete AFTER DELETE ON manual_asset_details WHEN NOT EXISTS(SELECT 1 FROM workspace_guards WHERE owner_id=OLD.owner_id) BEGIN UPDATE profiles SET revision=revision+1 WHERE owner_id=OLD.owner_id; END;
